namespace DsaAcademy.Content;

// Canonical time/space complexity for every practice concept's reference approach, used by
// the "Name the complexity" check under each lesson. Kept in one table rather than as a
// property on each concept file: it's pure metadata with no behavior, and one
// table is easier to audit for consistency than dozens of scattered one-liners. AlsoTime/AlsoSpace
// list other answers that are equally defensible (e.g. recursive vs. iterative space) so the
// check never marks a legitimately correct answer wrong.
public record ComplexityInfo(
    string Time,
    string Space,
    string Note,
    string[]? AlsoTime = null,
    string[]? AlsoSpace = null);

public static class ComplexityCatalog
